// The worker-sca manifests (workers/sca/tools.d) are parsed against REAL
// tool output: the fixtures in testdata/manifests/sca were generated by
// running each manifest's command (the pathos-sca helper) in the
// b2-pathos-worker-sca:dev image on testdata/manifests/sca/sample (or
// sample-depcheck) mounted at /work/fixture/src, e.g.
//
//	docker run --rm --network none --entrypoint /opt/pathos/sca/bin/pathos-sca \
//	  -v $PWD/testdata/manifests/sca/sample:/work/fixture/src:ro -v /tmp/out:/out b2-pathos-worker-sca:dev \
//	  cargo-audit /work/fixture/src /out/cargo-audit.json /tmp/x
//
// The offline tools (cargo-audit, bundler-audit, Retire.js,
// pathos-depcheck, cdxgen) ran with --network none. The registry tools
// (govulncheck, pip-audit, npm/yarn/pnpm audit, Composer audit, GuardDog,
// Dependency-Check) need their registries and ran with network access
// (the default bridge network), as they do through the egress proxy in a
// deployment. Dependency-Check ran on a copy of the sample with one more
// file, lib/commons-text-1.9.jar: a zip holding only
// META-INF/MANIFEST.MF and META-INF/maven/org.apache.commons/commons-text/
// pom.properties (groupId org.apache.commons, artifactId commons-text,
// version 1.9), not committed; its NVD data came from the NVD JSON 2.0
// data feeds (no API key).

const scaManifests = "../../../workers/sca/tools.d"

func loadSCASpec(t *testing.T, file string) PluginDef {
	t.Helper()
	raw, err := os.ReadFile(filepath.Join(scaManifests, file))
	if err != nil {
		t.Fatal(err)
	}
	d, err := decodeManifestSpec(raw, true)
	if err != nil {
		t.Fatalf("%s: %v", file, err)
	}
	return d
}

type scaCase struct {
	manifest, fixture, key, category, parser, network string
	ids                                               []string // rule ids or CVEs that must be found
	min                                               int
	lines                                             bool // findings have a line
}

var scaCases = []scaCase{
	{"govulncheck.yaml", "govulncheck.json", "govulncheck", "sca", "import:govulncheck", "registry", []string{"GO-2022-1059", "CVE-2022-32149"}, 1, false},
	{"pip-audit.yaml", "pip-audit.json", "pip-audit", "sca", "import:pip-audit", "registry", []string{"PYSEC-2023-74", "CVE-2023-32681"}, 10, false},
	{"cargo-audit.yaml", "cargo-audit.json", "cargo-audit", "sca", "import:cargo-audit", "none", []string{"RUSTSEC-2021-0003", "RUSTSEC-2020-0071"}, 2, false},
	{"bundler-audit.yaml", "bundler-audit.json", "bundler-audit", "sca", "import:bundler-audit", "none", []string{"CVE-2020-8161", "CVE-2018-16471"}, 10, false},
	{"retirejs.yaml", "retirejs.json", "retirejs", "sca", "import:retire-js", "none", []string{"CVE-2012-6708", "CVE-2015-9251"}, 3, false},
	{"npm-audit.yaml", "npm-audit.json", "npm-audit", "sca", "import:npm-audit", "registry", []string{"GHSA-jf85-cpcp-j695"}, 4, false},
	{"yarn-audit.yaml", "yarn-audit.jsonl", "yarn-audit", "sca", "import:yarn-audit", "registry", []string{"GHSA-jf85-cpcp-j695", "CVE-2021-44906"}, 4, false},
	{"pnpm-audit.yaml", "pnpm-audit.json", "pnpm-audit", "sca", "import:pnpm-audit", "registry", []string{"GHSA-jf85-cpcp-j695", "GHSA-xvch-5gv4-984h"}, 4, false},
	{"composer-audit.yaml", "composer-audit.json", "composer-audit", "sca", "import:composer-audit", "registry", []string{}, 5, false},
	{"dependency-check.yaml", "dependency-check.json", "dependency-check", "sca", "import:dependency-check", "registry", []string{"CVE-2022-42889"}, 1, false},
	{"guarddog.yaml", "guarddog.sarif", "guarddog", "malware", "sarif", "registry", []string{"capability-process-spawn"}, 5, true},
	{"pathos-depcheck.yaml", "pathos-depcheck.json", "pathos-depcheck", "supply-chain", "jsonmap", "none",
		[]string{"DEPCHECK-PIP-EXTRA-INDEX", "DEPCHECK-TYPOSQUAT-PYPI", "DEPCHECK-TYPOSQUAT-NPM", "DEPCHECK-NPM-UNMAPPED-SCOPE"}, 5, true},
}

func TestSCAManifestsParseRealOutput(t *testing.T) {
	for _, c := range scaCases {
		t.Run(c.key, func(t *testing.T) {
			d := loadSCASpec(t, c.manifest)
			if d.Key() != c.key || d.Category != c.category || d.ToolParser().String() != c.parser || !d.FirstParty {
				t.Fatalf("manifest: key %s category %s parser %s", d.Key(), d.Category, d.ToolParser().String())
			}
			if d.Network != c.network || d.Intrusive || !d.RunsOn("") || d.RunsOn("url") {
				t.Errorf("repository tool, network %s: %+v", c.network, d)
			}
			if d.LicenseSPDX == "" || d.Family != "sca" || len(d.ScanTypes) == 0 || d.DefaultEnabled {
				t.Errorf("licence, family, scan types, off by default: %+v", d)
			}
			sc, _ := scanners.Lookup(c.key)
			if !sc.AdapterAvailable || sc.Family != "sca" || !scanners.ManifestRouted(c.key) || sc.License != d.LicenseSPDX || sc.Network != c.network {
				t.Errorf("catalog entry: %+v", sc)
			}
			for _, st := range d.ScanTypes {
				if !slices.Contains(scanners.ScanTypesOf(c.key), st) {
					t.Errorf("scan type %s of the manifest is not registered for %s (%v)", st, c.key, scanners.ScanTypesOf(c.key))
				}
			}
			raw, err := os.ReadFile(filepath.Join("testdata", "manifests", "sca", c.fixture))
			if err != nil {
				t.Fatal(err)
			}
			fs, err := scanners.ParseToolOutput(d.Key(), d.ToolParser(), raw)
			if err != nil {
				t.Fatalf("parse: %v", err)
			}
			if len(fs) < c.min {
				t.Fatalf("findings: %d, want at least %d", len(fs), c.min)
			}
			var ids []string
			fps := map[string]string{}
			for _, f := range fs {
				ids = append(ids, f.RuleID, f.CVE)
				if f.ScannerKey != c.key || f.Category == "" || f.Fingerprint == "" || f.Title == "" {
					t.Errorf("finding: %+v", f)
				}
				if c.category != "malware" && f.Category != c.category && f.Category != "other" {
					t.Errorf("category %s: %+v", f.Category, f)
				}
				if strings.HasPrefix(f.FilePath, "/") || strings.HasPrefix(f.FilePath, "work/") {
					t.Errorf("repository-relative path: %q", f.FilePath)
				}
				if c.lines && (f.StartLine == nil || *f.StartLine <= 0) {
					t.Errorf("line: %+v", f)
				}
				if scanners.SeverityRank(f.Severity) == 0 && f.Severity != "info" {
					t.Errorf("severity %q", f.Severity)
				}
				// Equal fingerprints are the same advisory of the same
				// package (pip-audit's report lists some advisories twice;
				// the ingestion merges them).
				what := f.RuleID + " " + f.PackageName + " " + f.FilePath
				if w, ok := fps[f.Fingerprint]; ok && w != what {
					t.Errorf("fingerprint of %s and %s", w, what)
				}
				fps[f.Fingerprint] = what
				loc, err := scanners.LocateToolOutput(d.Key(), d.ToolParser(), raw, f.Fingerprint)
				if err != nil || loc == nil || len(loc.Raw) == 0 {
					t.Errorf("locate %s: %v", f.RuleID, err)
				}
			}
			if len(fps) != len(fs) && c.key != "pip-audit" {
				t.Errorf("fingerprints are distinct: %d of %d", len(fps), len(fs))
			}
			for _, id := range c.ids {
				if !slices.Contains(ids, id) {
					t.Errorf("%s not found in %v", id, ids)
				}
			}
		})
	}
}

// Every shipped manifest is covered above, except cdxgen (an SBOM, tested
// below), and loads as a first-party tool.
func TestSCAManifestsLoad(t *testing.T) {
	dir := t.TempDir()
	bin := fakeTool(t, dir)
	conf := filepath.Join(dir, "tools.d")
	_ = os.MkdirAll(conf, 0o755)
	entries, _ := os.ReadDir(scaManifests)
	var files []string
	for _, e := range entries {
		files = append(files, e.Name())
		raw, _ := os.ReadFile(filepath.Join(scaManifests, e.Name()))
		body := strings.Replace(string(raw), "command: /opt/pathos/sca/bin/pathos-sca", "command: "+bin, 1)
		_ = os.WriteFile(filepath.Join(conf, e.Name()), []byte(body), 0o644)
	}
	defs := LoadToolManifests(conf, slog.New(slog.NewTextHandler(io.Discard, nil)))
	if len(defs) != len(files) {
		t.Fatalf("loaded %d of %d manifests", len(defs), len(files))
	}
	for _, d := range defs {
		if d.Key() == scanners.CDXGen {
			continue
		}
		if !slices.ContainsFunc(scaCases, func(c scaCase) bool { return c.key == d.Key() }) {
			t.Errorf("%s has no fixture test", d.Key())
		}
		// The helper's first argument names the tool for --version too.
		if len(d.VersionArgs) != 2 || d.Args[0] != d.VersionArgs[0] || d.VersionArgs[1] != "--version" {
			t.Errorf("%s: version args %v, args %v", d.Key(), d.VersionArgs, d.Args)
		}
		// Tools that contact a registry say so; the others get no proxy.
		sc, _ := scanners.Lookup(d.Key())
		if d.Network != sc.Network {
			t.Errorf("%s: network %s, catalog %s", d.Key(), d.Network, sc.Network)
		}
	}
}

// cdxgen's CycloneDX SBOM is an inventory: the ingestion stores it like
// Syft's and parses no findings from it.
func TestCDXGenManifestAndSBOM(t *testing.T) {
	d := loadSCASpec(t, "cdxgen.yaml")
	if d.Key() != scanners.CDXGen || d.Category != "sbom" || d.Network != "none" || !scanners.IsSBOMTool(d.Key()) || !scanners.IsSBOMTool(scanners.Syft) ||
		scanners.IsSBOMTool("govulncheck") {
		t.Fatalf("cdxgen manifest: %+v", d)
	}
	if !slices.Contains(scanners.ScanTypesOf(scanners.CDXGen), "sbom") {
		t.Error("cdxgen covers the sbom scan type")
	}
	raw, err := os.ReadFile(filepath.Join("testdata", "manifests", "sca", "cdxgen.cdx.json"))
	if err != nil {
		t.Fatal(err)
	}
	// The SBOM is stored as the inventory: the same CycloneDX reader as
	// Syft's (vuln.StoreSBOM) finds the components of every ecosystem.
	var bom struct {
		BOMFormat   string `json:"bomFormat"`
		SpecVersion string `json:"specVersion"`
		Components  []struct {
			Name, Version, PURL string
		} `json:"components"`
	}
	if err := json.Unmarshal(raw, &bom); err != nil || bom.BOMFormat != "CycloneDX" || bom.SpecVersion != "1.6" {
		t.Fatalf("bom: %v %s %s", err, bom.BOMFormat, bom.SpecVersion)
	}
	var purls []string
	for _, c := range bom.Components {
		purls = append(purls, c.PURL)
	}
	for _, p := range []string{"pkg:npm/lodash@4.17.11", "pkg:pypi/requests@2.25.0", "pkg:golang/golang.org/x/text@v0.3.7",
		"pkg:cargo/smallvec@1.6.0", "pkg:gem/rack@2.0.1", "pkg:npm/jquery@1.8.1"} {
		if !slices.Contains(purls, p) {
			t.Errorf("component %s not in %v", p, purls)
		}
	}
	comps, err := vuln.ParseCycloneDX(raw)
	if err != nil || len(comps) < len(bom.Components)-1 {
		t.Errorf("inventory: %d components, %v", len(comps), err)
	}
}
